# ① 阿里云 CDN：URL 刷新与预热
aliyun cdn RefreshObjectCaches \
  --ObjectPath "https://www.example.com/app.js,https://www.example.com/index.html" \
  --ObjectType File

aliyun cdn PushObjectCache \
  --ObjectPath "https://www.example.com/big/package-1.2.0.apk"

# ② AWS CloudFront：创建缓存失效（invalidation）
aws cloudfront create-invalidation \
  --distribution-id EDFDVBD6EXAMPLE \
  --paths "/index.html" "/assets/app.js"

